const form=document.querySelector('#form'),canvas=document.querySelector('#receipt'),ctx=canvas.getContext('2d');
const titles={sell:'Sell crypto',buy:'Buy crypto',swap:'Swap crypto',fx:'Currency exchange'};
const assets=['USDT','USDC','BTC','ETH','SOL'],fiats=['NGN','USD','GBP','EUR','CAD','GHS'];
let draft={},receipts=[],readyFile=null,installPrompt=null;
try{draft=JSON.parse(localStorage.getItem('ezzy-draft')||'{}');receipts=JSON.parse(localStorage.getItem('ezzy-receipts')||'[]')}catch{}
const field=(name,label,options={})=>{if(options.list)return `<label>${label}<select name="${name}">${options.list.map(x=>`<option>${x}</option>`).join('')}</select></label>`;return `<label>${label}<input name="${name}" ${options.number?'type="number" min="0.00000001" step="any"':'type="text" maxlength="120"'} ${options.required?'required':''} placeholder="${options.placeholder||'Optional'}"></label>`};
function fields(type){let content='<div class="grid">'+field('sent','Customer sends',{number:true,required:true,placeholder:'0.00'})+field('sentCurrency','Currency / asset',{list:type==='buy'?fiats:type==='fx'?fiats:assets})+'</div><div class="grid">'+field('received','Customer receives',{number:true,required:true,placeholder:'0.00'})+field('receivedCurrency','Currency / asset',{list:type==='sell'||type==='fx'?fiats:assets})+'</div>';
content+='<div class="grid">'+field('rate','Agreed rate',{placeholder:'e.g. 1 USDT = 1,600 NGN'})+'<label>Fee (in currency sent)<input name="fee" type="number" min="0" step="any" placeholder="0.00"></label></div>';
if(type!=='fx')content+='<div class="grid">'+field('network',type==='swap'?'Receiving network':'Network',{placeholder:'e.g. TRC20'})+field('wallet',type==='sell'?'Deposit wallet':'Receiving wallet',{placeholder:'Wallet address'})+'</div>'+field('hash','Blockchain transaction hash');
if(type==='swap')content+='<div class="grid">'+field('sendNetwork','Sending network')+field('sendWallet','Sending wallet')+'</div>';
if(type!=='swap')content+='<div class="grid">'+field('bank',type==='buy'?'Payment bank':'Receiving bank')+field('accountName','Account name')+'</div>'+field('accountNumber',type==='buy'?'Payment account number':'Receiving account number');
document.querySelector('#dynamic').innerHTML=content;}
function initial(){const now=new Date();return {type:'sell',status:'Completed',sentCurrency:'USDT',receivedCurrency:'NGN',date:new Date(now-now.getTimezoneOffset()*60000).toISOString().slice(0,16),reference:'EZ-'+now.toISOString().slice(0,10).replaceAll('-','')+'-'+crypto.randomUUID().slice(0,6).toUpperCase()}}
function load(d){fields(d.type||'sell');for(const [key,value]of Object.entries(d)){if(form.elements.namedItem(key))form.elements.namedItem(key).value=value}readyFile=null;document.querySelector('#generated').hidden=true;draw();}
function data(){return Object.fromEntries(new FormData(form))}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',4500)}
function persist(){try{localStorage.setItem('ezzy-draft',JSON.stringify(data()))}catch{toast('Device storage is unavailable. You can still download this receipt.')}}
function amount(value,currency){return `${Number(value||0).toLocaleString('en-NG',{maximumFractionDigits:8})} ${currency||''}`}
function text(value,x,y,size,color='#163f35',weight='normal',max=900,baseline='alphabetic'){ctx.textBaseline=baseline;ctx.fillStyle=color;ctx.font=`${weight} ${size}px Arial`;while(ctx.measureText(String(value)).width>max&&size>13){size--;ctx.font=`${weight} ${size}px Arial`}ctx.fillText(String(value),x,y)}
function lines(value,max,size=25){ctx.font=`${size}px Arial`;const result=[];for(let segment of String(value).split('\n')){let line='';for(const word of segment.split(' ')){if(ctx.measureText(line+word).width>max&&line){result.push(line.trim());line=''}if(ctx.measureText(word).width>max){for(const char of word){if(ctx.measureText(line+char).width>max){result.push(line);line=''}line+=char}line+=' '}else line+=word+' '}result.push(line.trim())}return result}
const logo=new Image();logo.src='assets/logo.svg';logo.onload=()=>draw();
function rowSet(d){const rows=[['Customer',d.customer||'Your customer'],['Transaction',titles[d.type]],['Customer sends',d.sent?amount(d.sent,d.sentCurrency):'—'],['Customer receives',d.received?amount(d.received,d.receivedCurrency):'—']];for(const [key,label]of [['rate','Agreed rate'],['fee','Fee'],['network',d.type==='swap'?'Receiving network':'Network'],['wallet',d.type==='sell'?'Deposit wallet':'Receiving wallet'],['sendNetwork','Sending network'],['sendWallet','Sending wallet'],['hash','Transaction hash'],['bank',d.type==='buy'?'Payment bank':'Receiving bank'],['accountName','Account name'],['accountNumber',d.type==='buy'?'Payment account':'Receiving account']]){if(d[key])rows.push([label,key==='fee'?amount(d[key],d.sentCurrency):d[key]])}rows.push(['Reference',d.reference]);const date=new Date(d.date);rows.push(['Date & time',Number.isNaN(date.getTime())?'—':new Intl.DateTimeFormat('en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(date)]);return rows}
function draw(){const d=data(),rows=rowSet(d);let rowsHeight=0;const wrapped=rows.map(([label,value])=>{const list=lines(value,580);rowsHeight+=Math.max(63,list.length*33+25);return [label,list]});const note=d.note?lines(d.note,890,26):[];canvas.height=720+rowsHeight+(note.length?note.length*34+65:0);const h=canvas.height;
ctx.fillStyle='#fffdf5';ctx.fillRect(0,0,1080,h);ctx.fillStyle='#123f35';ctx.fillRect(0,0,1080,345);ctx.save();ctx.beginPath();ctx.rect(0,0,1080,345);ctx.clip();ctx.strokeStyle='#2b5b49';ctx.lineWidth=1;for(let i=0;i<5;i++){ctx.beginPath();ctx.arc(1030,40,140+i*70,0,Math.PI*2);ctx.stroke()}ctx.restore();if(logo.complete&&logo.naturalWidth)ctx.drawImage(logo,65,55,68,68);text('EzzyFx',145,102,45,'#eff5d7','bold');text('TRANSACTION RECEIPT',70,175,18,'#b8cfab','bold');text(d.received?amount(d.received,d.receivedCurrency):'Your next trade.',70,244,66,'#fffdf5','bold',925);text(titles[d.type],73,289,23,'#bccfb8');
const colors={Completed:['#e6efdd','#347343'],Processing:['#fff0c5','#846314'],Failed:['#f9ded8','#9b3a29'],Cancelled:['#eee9e0','#6c6255'],Reversed:['#e8e2f6','#6b4c89']};const [bg,fg]=colors[d.status]||colors.Processing;ctx.fillStyle=bg;ctx.beginPath();ctx.roundRect(70,382,265,53,26);ctx.fill();text(d.status==='Completed'?'✓  '+d.status:'•  '+d.status,98,417,24,fg,'bold');
let y=462;for(const [label,list]of wrapped){const height=Math.max(63,list.length*33+25);const center=y+height/2;text(label,70,center,25,'#81907b','normal',320,'middle');const valueTop=center-(list.length-1)*33/2;for(let i=0;i<list.length;i++)text(list[i],425,valueTop+i*33,25,'#173f34','bold',580,'middle');ctx.strokeStyle='#e4e7da';ctx.beginPath();ctx.moveTo(70,y+height);ctx.lineTo(1010,y+height);ctx.stroke();y+=height}
if(note.length){y+=30;text('NOTE',70,y+5,18,'#81907b','bold');y+=44;note.forEach(line=>{text(line,70,y,26);y+=34});y+=20}ctx.setLineDash([6,8]);ctx.strokeStyle='#cfd9c1';ctx.beginPath();ctx.moveTo(0,h-168);ctx.lineTo(1080,h-168);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle='#e8efdf';ctx.beginPath();ctx.arc(0,h-168,20,0,Math.PI*2);ctx.arc(1080,h-168,20,0,Math.PI*2);ctx.fill();text('Your next trade. Made Ezzy.',70,h-84,34,'#163f35','bold',650,'middle');text('WHATSAPP',775,h-105,17,'#7b8d71','bold');text('08147576669',775,h-62,28,'#163f35','bold',250)}
function valid(){if(!form.reportValidity())return false;const d=data();if(d.sentCurrency===d.receivedCurrency){toast('Choose different sending and receiving currencies.');return false}return true}
async function file(){if(!valid())return null;draw();const d=data();const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!blob)throw Error('Image generation failed');return new File([blob],`EzzyFx-${d.reference.replace(/[^a-z0-9_-]/gi,'-')}.png`,{type:'image/png'})}
function saveHistory(){const d=data();receipts=receipts.filter(x=>x.reference!==d.reference);receipts.unshift(d);receipts=receipts.slice(0,50);try{localStorage.setItem('ezzy-receipts',JSON.stringify(receipts));renderHistory()}catch{toast('Receipt generated, but device storage is full. Download to keep it.')}}
function renderHistory(){const root=document.querySelector('#history');root.replaceChildren();if(!receipts.length){const p=document.createElement('p');p.className='empty';p.textContent='Your generated receipts will appear here.';root.append(p)}receipts.forEach((d,i)=>{const item=document.createElement('div');item.className='history-item';const info=document.createElement('div');info.className='info';const title=document.createElement('strong');title.textContent=d.customer+' · '+amount(d.received,d.receivedCurrency);const sub=document.createElement('small');sub.textContent=titles[d.type]+' / '+d.status+' / '+d.reference;info.append(title,sub);const open=document.createElement('button');open.textContent='Open ↗';open.onclick=()=>{load(d);persist();form.scrollIntoView({behavior:'smooth',block:'start'})};const remove=document.createElement('button');remove.textContent='Delete';remove.setAttribute('aria-label','Delete receipt '+d.reference);remove.onclick=()=>{if(confirm('Delete this receipt from this device?')){receipts.splice(i,1);try{localStorage.setItem('ezzy-receipts',JSON.stringify(receipts))}catch{}renderHistory()}};item.append(info,open,remove);root.append(item)})}
form.addEventListener('input',()=>{readyFile=null;document.querySelector('#generated').hidden=true;persist();draw()});form.elements.type.addEventListener('change',()=>{const d=data();fields(d.type);const currencies={sell:['USDT','NGN'],buy:['NGN','USDT'],swap:['USDT','BTC'],fx:['USD','NGN']};form.elements.sentCurrency.value=currencies[d.type][0];form.elements.receivedCurrency.value=currencies[d.type][1];persist();draw()});
form.onsubmit=async e=>{e.preventDefault();try{readyFile=await file();if(readyFile){saveHistory();document.querySelector('#generated').hidden=false;toast('Receipt ready. Download or share it.')}}catch{toast('Unable to generate image. Please try again.')}};
document.querySelector('#new').onclick=()=>{if(form.elements.customer.value&&!confirm('Start a new receipt? Your current draft will be replaced.'))return;form.reset();load(initial());persist()};
function download(f){const url=URL.createObjectURL(f);const a=document.createElement('a');a.href=url;a.download=f.name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000)}
document.querySelector('#download').onclick=async()=>{try{const f=readyFile||await file();if(f){download(f);saveHistory();toast('Receipt downloaded.')}}catch{toast('Unable to download. Please try again.')}};
document.querySelector('#share').onclick=async()=>{try{const f=readyFile||await file();if(!f)return;saveHistory();if(navigator.canShare?.({files:[f]})){await navigator.share({files:[f],title:'EzzyFx transaction receipt'});toast('Receipt shared.')}else{download(f);toast('Image downloaded. Attach it in WhatsApp to share.')}}catch(e){if(e.name!=='AbortError')toast('Sharing could not finish. Use Download PNG instead.')}};
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});document.querySelector('#install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else document.querySelector('#install-help').showModal()};
load({...initial(),...draft});renderHistory();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
